import java.util.*;

class FreqCache {
    private final int capacity;
    private final Map<Integer, Integer> vals = new HashMap<>();
    private final Map<Integer, Integer> counts = new HashMap<>();
    private final Map<Integer, LinkedHashSet<Integer>> buckets = new HashMap<>(); // count -> keys, oldest first
    private int minCount = 0;

    public FreqCache(int capacity) {
        this.capacity = capacity;
    }

    public int get(int key) {
        if (!vals.containsKey(key)) return -1;
        touch(key);
        return vals.get(key);
    }

    public void put(int key, int value) {
        if (vals.containsKey(key)) {
            vals.put(key, value);
            touch(key);
            return;
        }
        if (vals.size() == capacity) {                      // evict LFU, oldest among ties
            int victim = buckets.get(minCount).iterator().next();
            buckets.get(minCount).remove(victim);
            vals.remove(victim);
            counts.remove(victim);
        }
        vals.put(key, value);
        counts.put(key, 1);
        buckets.computeIfAbsent(1, c -> new LinkedHashSet<>()).add(key);
        minCount = 1;                                       // a new key always has count 1
    }

    private void touch(int key) {                           // one more use of key
        int c = counts.get(key);
        LinkedHashSet<Integer> set = buckets.get(c);
        set.remove(key);
        if (set.isEmpty() && c == minCount) minCount++;
        counts.put(key, c + 1);
        buckets.computeIfAbsent(c + 1, x -> new LinkedHashSet<>()).add(key); // most recent at the end
    }
}

