class FreqCache:
    def __init__(self, capacity: int):
        self.cap = capacity; self.kv = {}; self.cnt = {}; self.groups = defaultdict(OrderedDict); self.mn = 0
    def _touch(self, k):
        c = self.cnt[k]; del self.groups[c][k]
        if not self.groups[c]:
            del self.groups[c]
            if self.mn == c: self.mn = c + 1
        self.cnt[k] = c + 1; self.groups[c + 1][k] = None
    def get(self, key: int) -> int:
        if key not in self.kv: return -1
        self._touch(key); return self.kv[key]
    def put(self, key: int, value: int) -> None:
        if key in self.kv: self.kv[key] = value; self._touch(key); return
        if len(self.kv) >= self.cap:
            k, _ = self.groups[self.mn].popitem(last=False)
            if not self.groups[self.mn]: del self.groups[self.mn]
            del self.kv[k]; del self.cnt[k]
        self.kv[key] = value; self.cnt[key] = 1; self.groups[1][key] = None; self.mn = 1

