class FreqCache {
  constructor(capacity) { this.cap = capacity; this.m = new Map(); this.t = 0; }
  get(k) { const e = this.m.get(k); if (!e) return -1; e.c++; e.t = ++this.t; return e.v; }
  put(k, v) {
    const e = this.m.get(k); if (e) { e.v = v; e.c++; e.t = ++this.t; return; }
    if (this.m.size >= this.cap) { let bk = null, b = null; for (const [kk, x] of this.m) if (!b || x.c < b.c || (x.c === b.c && x.t < b.t)) { b = x; bk = kk; } this.m.delete(bk); }
    this.m.set(k, { v, c: 1, t: ++this.t });
  }
}
